    elif not isinstance(path, str):
        status = "error"
        out = _err("VALIDATION_ERROR", "path must be a string")
    else:
        if limit is not None and not isinstance(limit, int):
            status = "error"
            out = _err("VALIDATION_ERROR", "limit must be a non-negative integer or null")
        elif isinstance(limit, int) and limit < 0:
            status = "error"
            out = _err("VALIDATION_ERROR", "limit must be a non-negative integer or null")

    # Service caps
    MAX_LIMIT = 1000
    if out is None and limit is not None and limit > MAX_LIMIT:
        status = "error"
        out = _err("VALIDATION_ERROR", f"limit exceeds maximum of {MAX_LIMIT}")

    rows = None
    if out is None:
        # Read file
        try:
            with open(path, "r", encoding="utf-8", newline="") as f:
                raw = f.read()
        except FileNotFoundError:
            status = "error"
            out = _err("NOT_FOUND", f"File not found: {path}")
        except OSError:
            status = "error"
            out = _err("NOT_FOUND", f"File not readable: {path}")

    if out is None:
        # Parse CSV (try common delimiters)
        candidates = [",", ";", "\t", "|"]
        parsed = None
        last_err = None
        for delim in candidates:
            try:
                buf = io.StringIO(raw)
                reader = csv.DictReader(buf, delimiter=delim)
                if not reader.fieldnames:
                    continue
                tmp = []
                for r in reader:
                    if r is None:
                        continue
                    if all((v is None or str(v).strip() == "") for v in r.values()):
                        continue
                    tmp.append({k: (v if v is not None else "") for k, v in r.items()})
                if tmp:
                    parsed = tmp
                    break
            except csv.Error as e:
                last_err = str(e)
                continue

        if parsed is None:
            status = "error"
            out = _err("VALIDATION_ERROR", "path cannot be read as a valid employees CSV", detail=last_err)

        else:
            rows = parsed
            if limit is not None:
                rows = rows[:limit]
            if len(rows) == 0:
                status = "error"
                out = _err("VALIDATION_ERROR", "CSV has no readable rows")

    # Record usage/audit dynamics
    # Mailbox Archive Gateway schema doesn't declare an audit collection; implement local request log.
    log_name = "request_log.json"
