            "path": path,
            "status": status,
            "latency_ms": latency_ms,
        }
    )
    _save(log_name, logs)

    if out is not None:
        return out

    return {
        "data": rows,
        "meta": {
            "returned": len(rows),
            "limit": limit,
            "max_limit": MAX_LIMIT,
        },
    }

