def parse_sample_email(path=__import__("os").path.join((__import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0056000" if __import__("os").path.isdir("./environment_mix/0056000") else "/app/database")), 'sample_email.eml'), **_extra):
    import json, os, datetime
    import time
    from email import policy
    from email.parser import BytesParser

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0056000" if __import__("os").path.isdir("./environment_mix/0056000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "ok"
    out = None

    if path is None or not isinstance(path, str) or path.strip() == "":
        status = "error"
        out = _err("VALIDATION_ERROR", "path must be a non-empty string")

    msg = None
    if out is None:
        try:
            with open(path, "rb") as f:
                raw = f.read()
        except FileNotFoundError:
            status = "error"
            out = _err("NOT_FOUND", f"File not found: {path}")
        except OSError:
            status = "error"
            out = _err("NOT_FOUND", f"File not readable: {path}")

    if out is None:
        try:
            msg = BytesParser(policy=policy.default).parsebytes(raw)
        except (ValueError, TypeError):
            status = "error"
            out = _err("VALIDATION_ERROR", "content is not a valid RFC 5322 email message")

    headers = None
    body = None
    if out is None:
        headers = dict(msg.items()) if msg is not None else {}
        if not headers:
            status = "error"
            out = _err("VALIDATION_ERROR", "message lacks parsable headers")

    if out is None:
        # Extract a plain-text body part
        body = ""
        if msg.is_multipart():
            for part in msg.walk():
                ctype = part.get_content_type()
                disp = part.get_content_disposition()
                if ctype == "text/plain" and disp != "attachment":
                    try:
                        body = part.get_content()
                    except (LookupError, UnicodeError, ValueError):
                        body = ""
                    if isinstance(body, str) and body.strip() != "":
                        break
        else:
            if msg.get_content_type() == "text/plain":
                try:
                    body = msg.get_content()
                except (LookupError, UnicodeError, ValueError):
                    body = ""

        if not isinstance(body, str) or body.strip() == "":
            status = "error"
            out = _err("VALIDATION_ERROR", "message does not contain a plain-text part that can be returned as the body")

    # Record usage/audit dynamics
    log_name = "request_log.json"
    logs = _load(log_name)
    if not isinstance(logs, list):
        logs = []
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    latency_ms = int((time.time() - t0) * 1000)
    logs.append(
        {
            "timestamp": ts,
            "tool": "parse_sample_email",
            "path": path,
            "status": status,
            "latency_ms": latency_ms,
        }
    )
    _save(log_name, logs)

    if out is not None:
        return out

    return {"data": {"headers": headers, "body": body}}

